<script setup lang="ts">
import {computed} from 'vue';
import type {P1Config} from '@/views/AgentWork/interface';
import {defaultParkingFilter,defaultOfflineFilter} from './eventAssessment';
import {stateNames} from './catalog';
const props=defineProps<{taskId:string}>();
const draft=defineModel<P1Config>({required:true});
const eventType=computed(()=>props.taskId==='p1-parking'?'parking':'offline');
</script>
<template><details class="skill-parameters"><summary>参数详情</summary><div class="parameter-body">
<template v-if="taskId==='p1-parking'||taskId==='p1-offline'"><div class="parameter-grid"><label>{{eventType==='parking'?'停车':'离线'}}时长（分钟）<input v-model.number="draft[eventType].thresholdMinutes" type="number" min="1" step="1"/></label><label>重复提醒间隔（分钟）<input v-model.number="draft[eventType].repeatMinutes" type="number" min="1" step="1"/></label></div><label class="parameter-check"><input v-model="draft.assessments[eventType].enabled" type="checkbox"/>启用POI与LLM异常研判</label><label>POI查询范围（米）<input v-model.number="draft.assessments[eventType].radiusMeters" type="number" min="1" step="1" :disabled="!draft.assessments[eventType].enabled"/></label><label>过滤规则<textarea v-model="draft.assessments[eventType].filterRule" rows="3" :disabled="!draft.assessments[eventType].enabled" :placeholder="eventType==='parking'?defaultParkingFilter:defaultOfflineFilter"/></label><p class="parameter-note">查询范围内有POI不代表车辆位于设施内；证据不足时保留异常待复核。</p></template>
<div v-else-if="taskId==='p1-deviation'" class="parameter-grid"><label>偏离半径（米）<input v-model.number="draft.deviation.radiusMeters" type="number" min="1" step="1"/></label><label>重复提醒间隔（分钟）<input v-model.number="draft.deviation.repeatMinutes" type="number" min="1" step="1"/></label></div>
<template v-else-if="taskId==='p1-late'"><div class="parameter-grid"><section><label class="parameter-check"><input v-model="draft.lateDeparture.enabled" type="checkbox"/>启用晚发异常</label><label>晚发容许时间（分钟）<input v-model.number="draft.lateDeparture.graceMinutes" type="number" min="1" step="1" :disabled="!draft.lateDeparture.enabled"/></label></section><section><label class="parameter-check"><input v-model="draft.lateArrival.enabled" type="checkbox"/>启用晚到异常</label><label>晚到容许时间（分钟）<input v-model.number="draft.lateArrival.graceMinutes" type="number" min="1" step="1" :disabled="!draft.lateArrival.enabled"/></label></section></div></template>
<template v-else-if="taskId==='p1-status'"><fieldset><legend>围栏监听范围</legend><label class="parameter-check"><input v-model="draft.fenceTargets" type="checkbox" value="origin"/>起始地（进、出）</label><label class="parameter-check"><input v-model="draft.fenceTargets" type="checkbox" value="destination"/>目的地（进、出）</label></fieldset><fieldset><legend>围栏自动更新状态</legend><label v-for="state in (['loading','in_transit','arrived','completed'] as const)" :key="state" class="parameter-check"><input v-model="draft.statusUpdates" type="checkbox" :value="state"/>{{stateNames[state]}}</label></fieldset><p class="parameter-note">未勾选的状态不自动更新，已采集的围栏事实仍保留。</p></template>
<template v-else-if="taskId==='p1-weather'"><p>天气任务没有可调整的研判参数。监听启停在任务卡片操作，预计次日0点生效；最长72小时，运单结束提前停止，不发送车机提醒。</p></template>
<p class="parameter-note">手动调整与自然语言调整使用同一份草稿，保存前不生效。间隔是同一异常的重复提醒间隔。</p></div></details></template>
